// ─── MAIN ───
let created = 0;
const dataEntries = [];
const i18nEnEntries = [];
const i18nViEntries = [];
const langs = ["en", "vi", "zh", "ja", "ko", "es"];

function processMethod(m, mediaType, indexPrefix, indexStart) {
  const idx = indexStart;
  const dir = path.join(BASE, mediaType, m.id);
  const i18nDir = path.join(dir, "i18n");
  
  // Create directories
  fs.mkdirSync(i18nDir, { recursive: true });
  
  // Create page.tsx
  fs.writeFileSync(path.join(dir, "page.tsx"), createPageTsx(mediaType, m.id));
  
  // Create i18n files
  for (const lang of langs) {
    fs.writeFileSync(path.join(i18nDir, `${lang}.json`), createI18n(m, lang));
  }
  
  created++;
  
  // Collect data.ts entry
  const index = `${indexPrefix}-${String(idx).padStart(3, "0")}`;
  dataEntries.push(`    { id: "${m.id}", category: "${m.cat}" as Category, mediaType: "${mediaType}" as MediaType, weight: 0.02, year: ${m.year}, index: "${index}"},`);
  
  // Collect i18n entries
  i18nEnEntries.push(`        "${m.id}": { name: "${m.name_en}", description: "${m.desc_en.replace(/"/g, '\\"')}" },`);
  i18nViEntries.push(`        "${m.id}": { name: "${m.name_vi}", description: "${m.desc_vi.replace(/"/g, '\\"')}" },`);
}

// Process all methods
newImageMethods.forEach((m, i) => processMethod(m, "image", "I", 187 + i));
newVideoMethods.forEach((m, i) => processMethod(m, "video", "V", 166 + i));
newTextMethods.forEach((m, i) => processMethod(m, "text", "T", 150 + i));

console.log(`\n✅ Created ${created} methods (${newImageMethods.length} image + ${newVideoMethods.length} video + ${newTextMethods.length} text)`);

// Write data.ts entries to file
const dataOutput = dataEntries.join("\n");
fs.writeFileSync(path.join(__dirname, "data_entries.txt"), dataOutput);

// Write i18n entries
const i18nOutput = `// EN entries:\n${i18nEnEntries.join("\n")}\n\n// VI entries:\n${i18nViEntries.join("\n")}`;
fs.writeFileSync(path.join(__dirname, "i18n_entries.txt"), i18nOutput);

console.log(`📁 data_entries.txt and i18n_entries.txt written to scripts/`);
console.log(`\nTotal new: ${created} → Expected total: ${503 + created}`);
